      "footnotesUr": "[1] ”رَجِيمٌ“ مَرْجُومٌ کے معنی میں ہے، رَجْمٌ کے معنی ہیں سنگسار کرنا یعنی پتھر مارنے کے ہیں۔ شیطان کو رجیم اس لئے کہا گیا ہے کہ یہ سب آسمان کی طرف جانے کی کوشش کرتا ہے تو آسمان سے شہاب ثاقب اس پر ٹوٹ کر گرتے ہیں، پھر رجیم ملعون و مردود کے معنی میں بھی استعمال ہوتا ہے، کیونکہ جسے سنگسار کیا جاتا ہے اسے ہر طرف سے لعنت ملامت بھی کی جاتی ہے۔ یہاں اللہ تعالٰی نے یہی فرمایا ہے کہ ہم نے آسمانوں کی حفاظت فرمائی ہر شیطان رجیم سے۔ یعنی ان ستاروں کے ذریعے سے، کیونکہ یہ شیطان کو مار بھاگنے پر مجبور کر دیتے ہیں۔",
