      "ur": "ہاں مگر جو چوری چھپے سننے کی کوشش کرے اس کے پیچھے دہکتا ہوا (کھلا شعلہ) لگتا ہے.[1]",
      "en": "Except one who steals a hearing and is pursued by a clear burning flame.",
      "footnotesUr": "[1] اس کا مطلب یہ ہے کہ شیاطین آسمانوں پر باتیں سننے کے لئے جاتے ہیں، جن پر شہاب ثاقب ٹوٹ کر گرتے ہیں، جن سے کچھ تو جل مر جاتے ہیں اور کچھ بچ جاتے ہیں اور بعض سن آتے ہیں۔ حدیث میں اس کی تفسیر اس طرح آتی ہے۔ نبی (صلى الله عليه وسلم) فرماتے ہیں ”جب اللہ تعالٰی آسمان پر کوئی فیصلہ فرماتا ہے، تو فرشتے اسے سن کر اپنے پر یا بازو پھڑ پھڑاتے ہیں (عجز و مسکنت کے اظہار کے طور پر) گویا وہ کسی چٹان پر زنجیر کی آواز ہے۔ پھر جب فرشتوں کے دلوں سے اللہ کا خوف دور ہو جاتا ہے تو وہ ایک دوسرے سے پوچھتے ہیں، تمہارے رب نے کیا کہا؟ وہ کہتے ہیں، اس نے جو کہا حق کہا اور اور وہ بلند اور بڑا ہے (اس کے بعد اللہ کا وہ فیصلہ اوپر سے نیچے تک یکے بعد دیگرے سنایا جاتا ہے) اس موقع پر شیطان چوری چھپے بات سنتے ہیں۔ اور یہ چوری چھپے بات سننے والے شیطان، تھوڑے تھوڑے فاصلے سے ایک دوسرے کے اوپر ہوتے ہیں اور ایک آدھا حکم سن کر اپنے دوست نجومی یا کاہن کے کان میں پھونک دیتے ہیں، اور اس کے ساتھ سو جھوٹ ملا کر لوگوں کو بیان کرتا ہے (ملخصاً۔ صحیح بخاری تفسیر سورۂ حجر)",
