      "arFull": "قَالَ رَبِّ بِمَاۤ اَغْوَیْتَنِیْ لَاُزَیِّنَنَّ لَهُمْ فِی الْاَرْضِ وَلَاُغْوِیَنَّهُمْ اَجْمَعِیْنَ ۟ۙ",
