      "en": "It has seven gates; for every gate is of them [i.e., Satan's followers] a portion designated.\"",
      "footnotesUr": "[1] یعنی ہر دروازہ مخصوص قسم کے لوگوں کے لئے خاص ہوگا۔ مثلاً ایک دروازہ مشرکوں کے لئے، ایک دروازہ دھریوں کے لئے۔ ایک زندیقوں، ایک زانیوں کے لئے۔ سود خوروں، چوروں اور ڈاکوؤں کے لئے وغیرہ وغیرہ۔ یا سات دروازوں سے مراد سات طبق اور درجے ہیں۔ پہلا طبق یا درجہ جہنم ہے، دوسرا نطی۔ پھر حطمہ، پھر سعیر۔ پھر سقر، پھر حجیم، پھر ھاویہ، سب سے اوپر والا درجہ موحدین کے لئے ہوگا، جنہیں کچھ عرصہ سزا دینے کے بعد یا سفارش پر نکال لیا جائے گا، دوسرے میں یہودی، تیسرے میں عیسائی، چوتھے میں صابی، پانچویں میں مجوسی، چھٹے میں مشرکین اور ساتویں میں منافقین ہونگے، سب سے اوپر والے درجے کا نام جہنم ہے اس کے بعد اس ترتیب سے نام ہیں۔ (فتح القدیر)",
