      "ur": "وه بولے کیا ہم نے تجھے دنیا بھر (کی ٹھیکیداری) سے منع نہیں کر رکھا؟[1]",
      "en": "They said, \"Have we not forbidden you from [protecting] people?\"",
      "footnotesUr": "[1] انہوں نے بد اخلاقی کا مظاہرہ کرتے ہوئے کہا اے لوط! تو ان اجنبیوں کا کیا لگتا ہے؟ اور کیوں ان کی حمایت کرتا ہے؟ کیا ہم نے تجھے منع نہیں کیا ہے کہ اجنبیوں کی حمایت نہ کیا کر، یا ان کو اپنا مہمان نہ بنایا کر! یہ ساری گفتگو اس وقت ہوئی جب کہ حضرت لوط (عليه السلام) کو یہ علم نہیں تھا کہ یہ اجنبی مہمان اللہ کے بھیجے ہوئے فرشتے ہیں اور وہ اسی ناہنجار قوم کو تباہ کرنے کے لئے آئے ہیں جو ان فرشتوں کے ساتھ بد فعلی کے لئے مصر تھی، جیسا کہ سورہ ھود میں یہ تفصیل گزر چکی ہے۔ یہاں ان کے فرشتے ہونے کا ذکر پہلے آ گیا ہے۔",
