      "arFull": "قَالَ هٰۤؤُلَآءِ بَنٰتِیْۤ اِنْ كُنْتُمْ فٰعِلِیْنَ ۟ؕ",
      "ur": "(لوط علیہ السلام نے) کہا اگر تمہیں کرنا ہی ہے تو یہ میری بچیاں موجود ہیں.[1]",
      "en": "[Lot] said, \"These are my daughters[681] - if you would be doers [of lawful marriage].\"",
      "footnotesUr": "[1] یعنی ان سے تم نکاح کر لو یا پھر اپنی قوم کی عورتوں کو اپنی بیٹیاں کہا، تم عورتوں سے نکاح کر لو یا جن کے حبالہ عقد میں عورتیں ہیں، وہ ان سے اپنی خواہش پوری کریں۔",
      "footnotesEn": "[681] i.e., the women of his community who were lawful for marriage.",
