      "footnotesUr": "[1] ”أَيْكَةُ“ گھنے درخت کو کہتے ہیں۔ اس بستی میں گھنے درخت ہونگے۔ اس لئے انہیں ”اَصْحٰبُ الْاَيْكَةِ“ (بن یا جنگل والے) کہا گیا۔ مراد اس سے قوم شعیب ہے اور ان کا زمانہ حضرت لوط (عليه السلام) کے بعد ہے اور ان کا علاقہ حجاز اور شام کے درمیان قوم لوط کی بستیوں کے قریب ہی تھا۔ اسے مدین کہا جاتا ہے جو حضرت ابراہیم (عليه السلام) کے بیٹے یا پوتے کا نام تھا اور اسی کے نام پر بستی کا نام پڑ گیا تھا۔ ان کا ظلم یہ تھا کہ اللہ کے ساتھ شرک کرتے تھے، رہزنی ان کا شیوہ اور کم تولنا اور کم ناپنا ان کا وطیرہ تھا، ان پر جب عذاب آیا ایک بادل ان پر سایہ فگن ہو گیا پھر چنگھاڑ اور بھو نچال نے مل کر ان کو ہلاک کر دیا۔",
