      "ur": "جیسے کہ ہم نے ان تقسیم کرنے والوں پر اتارا.[1]",
      "en": "Just as We had revealed [scriptures] to the separators[685]",
      "footnotesUr": "[1] بعض مفسرین کے نزدیک أَنْزَلْنَا کا مفعول الْعَذَابَ محذوف ہے۔ معنی یہ ہیں کہ میں تمہیں کھل کر ڈرانے والا ہوں عذاب سے، مثل اس عذاب کے، جو مُقْتَسِمِينَ پر نازل ہوا، مُقْتَسِمِينَ کون ہیں؟ جنہوں نے کتاب الٰہی کے ٹکڑے ٹکڑے کر دیئے، بعض کہتے ہیں کہ اس سے قریش قوم مراد ہے، جنہوں نے اللہ کی کتاب کو تقسیم کر دیا، اس کے بعض حصے کو شعر، بعض کو سحر (جادو) بعض کو کہانت اور بعض کو اساطیرالأولین (پہلوں کی کہانیاں) قرار دیا، بعض کہتے ہیں کہ مُقْتَسِمِينَ سے اہل کتاب اور قرآن سے مراد تورات و انجیل ہیں۔ انہوں نے ان آسمانی کتابوں کو متفرق اجزاء میں بانٹ دیا تھا۔ بعض کہتے ہیں کہ یہ حضرت صالح (عليه السلام) کی قوم ہے جنہوں نے آپس میں قسم کھائی تھی کہ صالح (عليه السلام) اور ان کے گھر والوں کو رات کے اندھیرے میں قتل کر دیں گے «تَقَاسَمُوْا بِاللّٰهِ لَـنُبَيِّتَـنَّهٗ وَاَهْلَهٗ» (النمل: 49) اور آسمانی کتاب کو ٹکڑے ٹکڑے کر ڈالا۔ ”عِضِينَ“ کے ایک معنی یہ بھی کیے گئے ہیں کہ اس کی بعض باتوں پر ایمان رکھنا اور بعض کے ساتھ کفر کرنا۔",
      "footnotesEn": "[685] Those who separated from the teachings of their prophets. Another meaning is \"As We sent down [punishment] on the sworn opponents [to Allāh's message].\"",
